import { useState } from "react";
import { date } from "../domain.js";
import { InfoHint } from "./design.jsx";
import { PasswordField } from "./ux.jsx";
import { ActionForm, Modal, Reason, ResourceState, command, useResource } from "./ui.jsx";

/**
 * Admin portal › Người dùng: password reset requests sent from the login page.
 * The admin verifies the employee out of band, then either issues a temporary
 * password (generated by the system or typed by the admin; it is e-mailed to
 * the employee and must be changed at the first sign-in) or rejects the request.
 */
export default function PasswordResetRequests({ onChanged }) {
  const resource = useResource("/api/v1/auth/password-reset/requests");
  const [approve, setApprove] = useState(null);
  const [reject, setReject] = useState(null);
  const [mode, setMode] = useState("generated");
  const [notice, setNotice] = useState("");
  const items = resource.data?.items || [];

  const done = (message) => {
    setApprove(null);
    setReject(null);
    setMode("generated");
    setNotice(message);
    resource.reload();
    onChanged?.();
  };

  // Shown at the top of “Người dùng” only while something needs the admin.
  if (!items.length && !notice && !approve && !reject) return null;

  return (
    <section className="panel password-reset-panel" aria-label="Yêu cầu đặt lại mật khẩu">
      <div className="section-head">
        <div>
          <h2>
            Yêu cầu đặt lại mật khẩu
            {items.length > 0 && <span className="badge badge-warning password-reset-count">{items.length} đang chờ</span>}
            <InfoHint>
              Nhân viên gửi yêu cầu từ liên kết “Quên mật khẩu” ở trang đăng nhập; quản trị viên nhận email thông báo.
              Hãy xác minh danh tính qua một kênh độc lập (gặp trực tiếp, điện thoại nội bộ) rồi cấp mật khẩu tạm hoặc từ chối.
              Mật khẩu tạm được gửi đến email nhân viên, các phiên đăng nhập cũ bị vô hiệu và nhân viên bắt buộc đổi mật khẩu ở lần đăng nhập đầu tiên.
              Mỗi yêu cầu có hiệu lực 24 giờ.
            </InfoHint>
          </h2>
        </div>
        <button type="button" className="secondary" onClick={resource.reload}>Làm mới</button>
      </div>
      {notice && <output className="success">{notice}</output>}
      <ResourceState resource={resource}>
        {items.length ? (
          <div className="table-wrap">
            <table className="responsive-records password-reset-table">
              <thead>
                <tr><th>Nhân viên</th><th>Email</th><th>Phòng ban</th><th>Thời điểm gửi</th><th>Hết hạn</th><th>Thao tác</th></tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.id}>
                    <td data-label="Nhân viên">{item.display_name}</td>
                    <td data-label="Email">{item.email}</td>
                    <td data-label="Phòng ban">{item.department}</td>
                    <td data-label="Thời điểm gửi">{date(item.requested_at)}</td>
                    <td data-label="Hết hạn">{date(item.expires_at)}</td>
                    <td data-label="Thao tác">
                      <div className="password-reset-actions">
                        <button type="button" onClick={() => { setNotice(""); setApprove(item); }}>Cấp mật khẩu tạm</button>
                        <button type="button" className="secondary" onClick={() => { setNotice(""); setReject(item); }}>Từ chối</button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <p className="muted">Không có yêu cầu đặt lại mật khẩu đang chờ xử lý.</p>
        )}
      </ResourceState>

      {approve && (
        <Modal title={`Cấp mật khẩu tạm · ${approve.display_name}`} onClose={() => { setApprove(null); setMode("generated"); }}>
          <p className="muted">
            Chỉ tiếp tục sau khi đã xác minh {approve.email} qua một kênh độc lập. Mật khẩu tạm sẽ được gửi đến email
            của nhân viên; nhân viên phải đổi mật khẩu ngay ở lần đăng nhập đầu tiên.
          </p>
          <ActionForm
            submitLabel="Cấp mật khẩu tạm và gửi email"
            onSubmit={async (values) => {
              const body = { reason: values.reason, mode };
              if (mode === "manual") body.temporary_password = values.temporary_password;
              await command(`auth/password-reset/requests/${approve.id}/approve`, body);
              done(`Đã cấp mật khẩu tạm cho ${approve.email}; mật khẩu đã được gửi qua email.`);
            }}
          >
            <fieldset className="password-reset-mode">
              <legend>Cách tạo mật khẩu tạm</legend>
              <label className="radio-row">
                <input type="radio" name="mode_choice" checked={mode === "generated"} onChange={() => setMode("generated")} />
                <span><strong>Hệ thống tự sinh (khuyến nghị)</strong> — mật khẩu ngẫu nhiên 28 ký tự, không ai biết trước.</span>
              </label>
              <label className="radio-row">
                <input type="radio" name="mode_choice" checked={mode === "manual"} onChange={() => setMode("manual")} />
                <span><strong>Quản trị viên tự nhập</strong> — dùng khi cần đọc mật khẩu tạm cho nhân viên qua điện thoại.</span>
              </label>
            </fieldset>
            {mode === "manual" && (
              <PasswordField
                label="Mật khẩu tạm"
                name="temporary_password"
                required
                minLength={15}
                maxLength={128}
                autoComplete="new-password"
                help="Tối thiểu 15 ký tự, có chữ hoa, chữ thường, chữ số, ký tự đặc biệt và không chứa tên email của nhân viên."
              />
            )}
            <Reason label="Cách đã xác minh danh tính" placeholder="Ví dụ: đã gọi điện thoại nội bộ và đối chiếu mã nhân viên" />
          </ActionForm>
        </Modal>
      )}

      {reject && (
        <Modal title={`Từ chối yêu cầu · ${reject.display_name}`} onClose={() => setReject(null)}>
          <p className="muted">Mật khẩu hiện tại của nhân viên được giữ nguyên; nhân viên nhận email thông báo kèm lý do.</p>
          <ActionForm
            danger
            submitLabel="Từ chối yêu cầu"
            onSubmit={async (values) => {
              await command(`auth/password-reset/requests/${reject.id}/reject`, { reason: values.reason });
              done(`Đã từ chối yêu cầu của ${reject.email}.`);
            }}
          >
            <Reason label="Lý do từ chối" placeholder="Ví dụ: không xác minh được danh tính qua điện thoại nội bộ" />
          </ActionForm>
        </Modal>
      )}
    </section>
  );
}
